<script setup>
import { ref,computed } from 'vue'
import { Search, ArrowUpRight, Sparkles, LayoutGrid, Star, Flag, X, Leaf, CheckCircle2, CircleDashed, Timer } from 'lucide-vue-next'
import NavBar from './components/NavBar.vue'
import KanbanColumn from './components/KanbanColumn.vue'
import AddTaskModal from './components/AddTaskModal.vue'
import FunToast from './components/FunToast.vue'
import Celebration from './components/Celebration.vue'
import { useKanban } from './composables/useKanban'
const {tasks,columns,storageFailed,existingCategories,add,toggle,remove,move,reset}=useKanban()
const query=ref(''),filter=ref('all'),category=ref(''),modal=ref(false),initialColumn=ref('todo'),resetOpen=ref(false),celebrate=ref(false)
const completed=computed(()=>tasks.value.filter(t=>t.columnId==='done').length)
const progress=computed(()=>tasks.value.length?Math.round(completed.value/tasks.value.length*100):0)
const filtered=computed(()=>tasks.value.filter(t=>(!query.value||[t.title,t.description,t.category].join(' ').toLowerCase().includes(query.value.toLowerCase()))&&(!category.value||t.category===category.value)&&(filter.value==='all'||filter.value==='starred'&&t.starred||filter.value==='urgent'&&t.urgent)))
const hasFilter=computed(()=>!!query.value||!!category.value||filter.value!=='all')
const date=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())
function open(col='todo'){initialColumn.value=col;modal.value=true}
function submit(t){add(t);modal.value=false;if(t.columnId==='done')celebrate.value=true}
function moved(id,col,index){if(move(id,col,index))celebrate.value=true}
function exportTasks(){const url=URL.createObjectURL(new Blob([JSON.stringify(tasks.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`拾序任务备份-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><div class="app-shell"><NavBar :tasks="tasks" @add-task="open()" @reset="resetOpen=true" @export="exportTasks"/><main><section class="intro"><div class="intro-copy"><div class="eyebrow"><span class="tiny-line"></span>YOUR SPACE, YOUR PACE</div><h1>心有计划，<span>行有方向。</span><i>✳</i></h1><p>把纷繁留给看板，把专注留给自己。</p><div class="date-line">{{date}}<span>·</span>今天也向前一点点</div></div><aside class="progress-card"><div class="progress-head"><span><Sparkles :size="14"/>一点点，积累成就感</span><ArrowUpRight :size="17"/></div><div class="progress-value">{{progress}}<small>%</small><span>已完成 {{completed}} / {{tasks.length}} 个任务</span></div><div class="progress-track"><i :style="{width:progress+'%'}"></i></div><p>{{progress===100?'所有任务都完成了，享受此刻吧。':'不必一口气完成，只要持续向前。'}}</p></aside></section><section class="overview" aria-label="任务统计"><div><span class="stat-icon lavender"><LayoutGrid :size="19"/></span><span class="stat-label">全部任务</span><strong>{{tasks.length.toString().padStart(2,'0')}}</strong></div><div><span class="stat-icon neutral"><CircleDashed :size="19"/></span><span class="stat-label">等待开始</span><strong>{{tasks.filter(t=>t.columnId==='todo').length.toString().padStart(2,'0')}}</strong></div><div><span class="stat-icon lavender"><Timer :size="19"/></span><span class="stat-label">正在进行</span><strong>{{tasks.filter(t=>t.columnId==='doing').length.toString().padStart(2,'0')}}</strong></div><div><span class="stat-icon mint"><CheckCircle2 :size="19"/></span><span class="stat-label">已经完成</span><strong>{{completed.toString().padStart(2,'0')}}</strong></div></section><section class="workspace"><div class="workspace-heading"><div><h2>我的任务板</h2><span class="workspace-note">把计划，变成一点一滴的行动。</span></div><span class="drag-note"><span>↔</span> 拖动卡片，轻松流转</span></div><div class="toolbar"><div class="filter-tabs" aria-label="筛选任务"><button :class="{selected:filter==='all'}" :aria-pressed="filter==='all'" @click="filter='all'"><LayoutGrid :size="14"/>全部任务</button><button :class="{selected:filter==='starred'}" :aria-pressed="filter==='starred'" @click="filter='starred'"><Star :size="14"/>星标</button><button :class="{selected:filter==='urgent'}" :aria-pressed="filter==='urgent'" @click="filter='urgent'"><Flag :size="14"/>紧急</button></div><div class="search-controls"><select v-model="category" aria-label="按分类筛选"><option value="">所有分类</option><option v-for="c in existingCategories" :key="c" :value="c">{{c}}</option></select><label class="search"><Search :size="15"/><input v-model="query" placeholder="搜索任务…" aria-label="搜索任务"><button v-if="query" class="clear-search" aria-label="清空搜索" @click="query=''"><X :size="13"/></button></label></div></div><p v-if="storageFailed" class="storage-warning" role="alert">浏览器未能保存任务，请点击右上角导出备份。</p><div class="board"><KanbanColumn v-for="col in columns" :key="col.id" :column="col" :task-list="filtered.filter(t=>t.columnId===col.id)" :filtered="hasFilter" @add="open" @toggle="toggle" @remove="remove" @move="moved"/></div></section></main><footer class="page-footer"><span><Leaf :size="13"/>给生活一点秩序，给自己一点从容。</span><span>拾序 · 你的日常，自有节奏</span></footer><AddTaskModal v-if="modal" :columns="columns" :existing-categories="existingCategories" :initial-column="initialColumn" @submit="submit" @close="modal=false"/><div v-if="resetOpen" class="modal-backdrop" @click.self="resetOpen=false" @keydown.esc="resetOpen=false"><section class="modal confirm" role="alertdialog" aria-modal="true" aria-labelledby="reset-title"><h2 id="reset-title">清空看板，重新出发？</h2><p>这会删除全部 {{tasks.length}} 个任务，无法撤销。你可以先导出一份备份。</p><div class="confirm-actions"><button class="secondary-btn" autofocus @click="resetOpen=false">保留任务</button><button class="danger-btn" @click="reset();resetOpen=false">确认清空</button></div></section></div><FunToast/><Celebration :visible="celebrate" @complete="celebrate=false"/></div></template>
